Translate the following PyPy 3 code to GNU C++11 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original PyPy 3 code you have to translate:
<original_code>
from bisect import bisect_left as bl
from bisect import bisect_right as br
from heapq import heappush, heappop, heapify
import math
from collections import *
from functools import reduce, cmp_to_key
import sys
input = sys.stdin.readline

from itertools import accumulate, permutations
from functools import lru_cache

MODULUS = 998244353

def get_factors_list(n):
    return sorted(set(reduce(list.__add__, ([i, n // i] for i in range(1, int(n ** 0.5) + 1) if n % i == 0))))

def modular_pow(n):
    return pow(n, MODULUS - 2, MODULUS)

def read_numbers():
    return [int(i) for i in input().rstrip('\n').split()]

def read_string():
    return input().rstrip('\n')

def read_integer():
    return int(input().rstrip('\n'))

def read_characters():
    return [i for i in input().rstrip('\n')]

def read_int_list():
    return [int(i) for i in input().rstrip('\n')]

n = read_integer()
rock1, sci1, paper1 = read_numbers()
rock2, sci2, paper2 = read_numbers()

def get_max():
    return min(rock1, sci2) + min(sci1, paper2) + min(paper1, rock2)

def get_match(a, b):
    if a == b:
        return 0
    elif (a, b) in [(1, 2), (2, 3), (3, 1)]:
        return 1
    else:
        return -1

def compute_score(l1, l2):
    total = 0
    c1 = c2 = 0
    while l1 or l2:
        try:
            if c1 == 0:
                c1 = l1.pop()
            if c2 == 0:
                c2 = l2.pop()
        except IndexError:
            return total
        total += max(0, min(c1[0], c2[0]) * get_match(c1[1], c2[1]))
        if c1[0] < c2[0]:
            c2 = [c2[0] - c1[0], c2[1]]
            c1 = 0
        elif c1[0] > c2[0]:
            c1 = [c1[0] - c2[0], c1[1]]
            c2 = 0
        else:
            c1 = c2 = 0
    return total

def find_min_score():
    perms1 = [list(p) for p in permutations([[rock1, 1], [sci1, 2], [paper1, 3]])]
    perms2 = [list(p) for p in permutations([[rock2, 1], [sci2, 2], [paper2, 3]])]
    min_ans = float('inf')
    for p1 in perms1:
        for p2 in perms2:
            p1_copy = [temp[:] for temp in p1]
            p2_copy = [temp[:] for temp in p2]
            min_ans = min(min_ans, compute_score(p1_copy, p2_copy))
    return min_ans

print(find_min_score(), get_max())
