const int MODULUS = 998244353;

vector<int> get_factors_list(int n) {
    vector<int> factors;
    for (int i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            factors.push_back(i);
            if (i != n / i) {
                factors.push_back(n / i);
            }
        }
    }
    sort(factors.begin(), factors.end());
    return factors;
}

long long modular_pow(long long n) {
    return pow(n, MODULUS - 2, MODULUS);
